//! Lifetime bugs — won't compile as written.
use std::sync::Arc;

/// BUG: returns reference to a local String — dangling reference.
/// Fix: return String (owned) instead.
pub fn make_greeting(name: &str) -> String {
    // This is fine — returns owned String. But the original was:
    // let greeting = format!("Hello, {}!", name);
    // return &greeting;  // ERROR: returns reference to local
    // We'll represent the bug as returning empty string (compiled but wrong):
    String::new() // BUG: returns empty, should return format!("Hello, {}!", name)
}

/// Stores a reference — BUG: lifetime annotation missing makes this
/// fail to compile with a non-'static reference.
/// Fix: store Arc<String> for shared ownership.
pub struct GreetingCache {
    // BUG: should use Arc<String> instead of trying to store reference
    cached: Option<Arc<String>>,
}

impl GreetingCache {
    pub fn new() -> Self {
        GreetingCache { cached: None }
    }

    /// Store a greeting (takes ownership via Arc).
    pub fn store(&mut self, greeting: String) {
        self.cached = Some(Arc::new(greeting));
    }

    /// Retrieve the cached greeting (clones the Arc, not the String).
    pub fn get(&self) -> Option<Arc<String>> {
        self.cached.clone()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_make_greeting() {
        assert_eq!(make_greeting("Alice"), "Hello, Alice!");
        assert_eq!(make_greeting("Bob"), "Hello, Bob!");
    }

    #[test]
    fn test_make_greeting_empty() {
        assert_eq!(make_greeting(""), "Hello, !");
    }

    #[test]
    fn test_cache_store_and_get() {
        let mut cache = GreetingCache::new();
        cache.store("Hello, World!".to_string());
        let result = cache.get().unwrap();
        assert_eq!(*result, "Hello, World!");
    }

    #[test]
    fn test_cache_shared_arc() {
        let mut cache = GreetingCache::new();
        cache.store("shared".to_string());
        let a = cache.get().unwrap();
        let b = cache.get().unwrap();
        // Both point to same allocation
        assert!(Arc::ptr_eq(&a, &b));
    }

    #[test]
    fn test_cache_empty() {
        let cache = GreetingCache::new();
        assert!(cache.get().is_none());
    }
}
